<script setup lang="ts">
import {ref,computed,nextTick,watch,onUnmounted} from 'vue'
import {ArrowDown,Copy,Square,RotateCcw} from 'lucide-vue-next'
import type {GenerationController} from '../api/generation-controller'
import type {GenerationAcceptResult,GenerationChapter} from '../api/generation-types'
import {createGenerationFollowing} from '../api/generation-follow'
import {generationReadOnly} from '../api/generation-stream'
import {useApp} from '../stores/app'
import '../styles/story-generation.css'
import EventLedgerPanel from '../writing/EventLedgerPanel.vue'
import AcceptedBasisPanel from '../writing/AcceptedBasisPanel.vue'
const props=defineProps<{controller:GenerationController}>(),emit=defineEmits<{accepted:[GenerationAcceptResult];read:[GenerationAcceptResult];listen:[GenerationChapter]}>(),store=useApp()
const value=computed(()=>props.controller.preview.value||props.controller.state.value),body=ref<HTMLElement>(),newWords=ref(false),localError=ref(''),rewriteOpen=ref(false),wish=ref(props.controller.rewriteIntent.value?.body.instruction||''),prefix=ref(0),versionChoice=ref(props.controller.state.value?.candidateVersion||1)
const historical=computed(()=>!!value.value&&generationReadOnly(value.value))
const awaitingConfirmation=computed(()=>props.controller.cached?.value===true)
function rawFor(chapter:GenerationChapter){
  if(chapter.rawPresentation)return chapter.rawPresentation
  const current=value.value
  return props.controller.receivedRaw?.value.find(r=>r.generationId===current?.id&&r.candidateVersion===current.candidateVersion&&r.contentId===chapter.contentId&&r.rawPresentation.chapterIndex===chapter.index)?.rawPresentation
}
watch(()=>value.value?.candidateVersion,version=>{if(version!==undefined)versionChoice.value=version},{immediate:true})
const pickedPrefix=ref(false)
watch([()=>value.value?.id,()=>value.value?.candidateVersion],()=>{pickedPrefix.value=false})
const choices=computed(()=>Array.from({length:props.controller.prefix.value},(_,i)=>i+1).filter(n=>n>(value.value?.acceptedPrefix||0)))
const follow=createGenerationFollowing();let disposed=false,renderVersion=0,settled:ReturnType<typeof setTimeout>|undefined
// Batch raw snapshots, then append to bounded Text nodes without replacing
// previously selectable nodes. The initial binding stays immutable in the DOM.
type TextBlock={initial:string;text:string;mutable:boolean}
const segments=ref<Record<string,{text:string;rendered:string;chunks:TextBlock[]}>>({})
const spanElements=new Map<string,HTMLElement>();let blockTimer:ReturnType<typeof setTimeout>|undefined
const graphemes=new Intl.Segmenter(undefined,{granularity:'grapheme'})
function blocks(text:string){const result:TextBlock[]=[];for(const {segment} of graphemes.segment(text)){const last=result.at(-1);if(last&&last.text.length+segment.length<=128){last.text+=segment;last.initial=last.text}else result.push({initial:segment,text:segment,mutable:false})}return result}
function syncBlock(element:HTMLElement|undefined,chunk:TextBlock){if(!element)return;const node=element.firstChild;if(node?.nodeType===3){const text=node as Text;if(chunk.text.startsWith(text.data))text.appendData(chunk.text.slice(text.data.length))}else if(chunk.initial!==chunk.text){
  // Non-DOM renderers (including SSR) render a snapshot rather than mutate Text.
  chunk.initial=chunk.text
}}
function bindBlock(key:string,index:number,element:unknown){const id=key+':'+index;if(!element){spanElements.delete(id);return}spanElements.set(id,element as HTMLElement);const chunk=segments.value[key]?.chunks[index];if(chunk)syncBlock(element as HTMLElement,chunk)}
function flushBlocks(){blockTimer=undefined;if(disposed)return;for(const [key,entry] of Object.entries(segments.value)){if(entry.text===entry.rendered)continue;const delta=entry.text.slice(entry.rendered.length);for(const {segment} of graphemes.segment(delta)){let tail=entry.chunks.at(-1);const joinsPrevious=/^[\p{M}\u200d\ufe0e\ufe0f]/u.test(segment);if(!tail?.mutable||(!joinsPrevious&&tail.text.length+segment.length>128)){tail={initial:segment,text:segment,mutable:true};entry.chunks.push(tail)}else tail.text+=segment}entry.rendered=entry.text;entry.chunks.forEach((chunk,index)=>syncBlock(spanElements.get(key+':'+index),chunk))}void followRender()}
watch(()=>value.value?.chapters,chapters=>{const keys=new Set<string>();for(const c of chapters||[]){const key=c.contentId+':'+c.streamVersion;keys.add(key);const old=segments.value[key];if(!old||!c.text.startsWith(old.text))segments.value[key]={text:c.text,rendered:c.text,chunks:blocks(c.text)};else if(c.text.length>old.text.length){old.text=c.text;if(blockTimer===undefined)blockTimer=setTimeout(flushBlocks,16)}}for(const key of Object.keys(segments.value))if(!keys.has(key)){delete segments.value[key];for(const id of spanElements.keys())if(id.startsWith(key+':'))spanElements.delete(id)}},{deep:false,immediate:true,flush:'sync'})
const status=computed(()=>{const v=value.value;if(!v)return '';if(awaitingConfirmation.value)return '本机草稿 · 等待联网确认';if(generationReadOnly(v))return v.state==='historical-unknown'?'导入历史 · 状态未记录':'导入历史 · 只读';if(v.persistenceState==='recoverable')return '正在恢复保存…';if(v.persistenceState==='unconfirmed')return '正文保存暂未确认';if(props.controller.active.value)return `正在写第 ${Math.min(v.completedChapters+1,v.requestedChapters)} / ${v.requestedChapters} 章`;return v.state==='cancelled'?'写作已停止，已收到的正文保留':v.state==='result-unknown'||v.providerState==='unknown'?'模型结果与用量暂未确认':`已保存 ${v.completedChapters} / ${v.requestedChapters} 章`})
async function followRender(changed=true){const version=++renderVersion;await nextTick();if(disposed||version!==renderVersion||!body.value)return;follow.render(body.value,changed);newWords.value=follow.newWords;clearTimeout(settled);settled=setTimeout(()=>follow.settled(),0)}
watch(()=>value.value?.chapters.map(c=>c.contentId+':'+c.streamVersion+':'+c.text.length).join('|'),()=>void followRender())
watch(()=>[props.controller.prefix.value,value.value?.acceptedPrefix] as const,([max,accepted])=>{if(value.value&&(!pickedPrefix.value||prefix.value<=(accepted||0)||prefix.value>max)){prefix.value=max;pickedPrefix.value=false}},{immediate:true})
function latest(){follow.latest();void followRender(false)}
function scroll(){const area=body.value;if(area){follow.scroll(area.scrollTop,area.scrollHeight,area.clientHeight);newWords.value=follow.newWords}}
function wheel(e:WheelEvent){follow.wheel(e.deltaY)}
function key(e:KeyboardEvent){follow.key(e.key)}
function stopFollowing(){follow.stop()}
async function copy(text:string){localError.value='';try{await navigator.clipboard.writeText(text);if(!disposed)store.message('正文已复制')}catch{if(!disposed)localError.value='暂时无法复制，可以选中正文手动复制'}}
async function accept(){const result=await props.controller.accept(prefix.value);if(result&&!disposed)emit('accepted',result)}
async function rewrite(){if(await props.controller.rewrite(wish.value)){rewriteOpen.value=false;wish.value='';follow.latest()}}
function hintMessage(code:string){return ({CHECK_UNAVAILABLE:'内容检查暂时不可用。',WRITING_INTERRUPTED:'后续写作中断，已完成正文保留。',TOO_SHORT:'篇幅短于目标。',CHAPTER_TOO_SHORT:'篇幅短于目标。',CHAPTER_TOO_LONG:'篇幅长于目标。',CHAPTER_REPETITIVE:'有重复段落，可在加入故事后编辑。',CHAPTER_PROGRESS_UNCERTAIN:'情节推进或写法可能需要调整。',CHAPTER_INTERRUPTED:'模型未正常结束，已收到内容保留。',CHAPTER_FORMAT:'模型返回格式尚未完整，原返回已保留。',CONTINUITY:'可能与已知设定冲突。',SPOILER:'可能包含后续剧情。',CHARACTER_VOICE:'角色说话方式可能需要调整。'} as Record<string,string>)[code]||'这段内容可能需要检查，正文已保留。'}
onUnmounted(()=>{disposed=true;renderVersion++;clearTimeout(settled);clearTimeout(blockTimer);spanElements.clear()})
</script>
<template><section v-if="value" class="generation-inline" aria-label="行内写作草稿" :data-generation-id="value.id" @pointerdown.stop @pointerup.stop @keydown.stop>
  <header class="generation-header"><div><small class="badge">{{historical?'导入历史':'AI 写作'}} · 候选 {{value.candidateVersion}}</small><p role="status" aria-live="polite">{{props.controller.preview.value?'较早的候选 · 只读':status}}</p></div><button v-if="!historical&&props.controller.active.value" class="icon-button" aria-label="停止写作并保留正文" :disabled="props.controller.busy.value||!store.online||awaitingConfirmation" @click="props.controller.cancel()"><Square :size="18"/></button></header>
  <div ref="body" class="generation-body" tabindex="0" aria-label="生成正文" @pointerdown="stopFollowing" @scroll="scroll" @wheel.passive="wheel" @keydown="key" @touchstart.passive="follow.touchStart($event.touches[0]?.clientY||0)" @touchmove.passive="follow.touchMove($event.touches[0]?.clientY||0)"><p v-if="!value.chapters.length" class="muted">{{historical?'没有可显示的正文':'正在准备正文…'}}</p>
    <article v-for="chapter in value.chapters" :key="chapter.contentId+':'+chapter.streamVersion" class="generation-chapter" :data-content-id="chapter.contentId"><div class="row between"><h3>{{chapter.title||'第 '+chapter.index+' 章'}}</h3><span class="badge">{{chapter.index<=value.acceptedPrefix?'已加入故事线':chapter.durability==='saved'&&chapter.completeness==='complete'?'已保存':chapter.durability==='unconfirmed'?'保存未确认':chapter.durability==='saving'?'正在保存':'草稿'}} · AI</span></div><div class="generation-prose" data-content-source="ai" :data-stream-version="chapter.streamVersion"><span v-for="(chunk,index) in segments[chapter.contentId+':'+chapter.streamVersion]?.chunks||[]" :key="index" :data-delta-index="index" :ref="element=>bindBlock(chapter.contentId+':'+chapter.streamVersion,index,element)">{{chunk.initial}}</span></div><EventLedgerPanel v-if="chapter.eventLedger" :ledger="chapter.eventLedger"/><details v-if="chapter.hints.length" class="generation-hints"><summary>内容提示 · {{chapter.hints.length}}</summary><p v-for="hint in chapter.hints" :key="hint.code">{{hint.message||hintMessage(hint.code)}}</p></details><details v-if="rawFor(chapter)" class="generation-raw"><summary>模型原返回</summary><small v-if="!chapter.rawPresentation">较早的原返回片段</small><section v-for="attempt in rawFor(chapter)!.attempts" :key="attempt.kind"><small>{{attempt.kind==='repair'?'格式修整':'原始请求'}}{{chapter.rawPresentation&&attempt.kind===chapter.rawPresentation.selected?' · 当前正文来源':''}}</small><pre>{{attempt.raw}}</pre><button @click="copy(attempt.raw)"><Copy :size="16"/>复制原返回</button></section></details><button :disabled="!chapter.text" @click="copy(chapter.text)"><Copy :size="16"/>复制这一章</button><button v-if="!props.controller.preview.value&&chapter.completeness==='complete'&&chapter.durability==='saved'&&chapter.contentHash" @click="emit('listen',chapter)">听这一章 · 已保存草稿</button></article>
  </div><button v-if="newWords" class="generation-latest" @click="latest"><ArrowDown :size="16"/>返回最新</button>
  <div class="generation-actions"><template v-if="!props.controller.preview.value&&props.controller.prefix.value>value.acceptedPrefix"><label>连续保存至<select v-model.number="prefix" aria-label="连续保存至章节" @change="pickedPrefix=true"><option v-for="number in choices" :key="number" :value="number">第 {{number}} 章</option></select></label><button class="primary" :disabled="props.controller.busy.value||!store.online||awaitingConfirmation" @click="accept">{{historical?'加入':'保存'}}{{prefix===value.requestedChapters?'全部完整章节':'前 '+prefix+' 章'}}</button></template><button v-if="!historical&&!props.controller.preview.value&&['recoverable','unconfirmed'].includes(value.persistenceState)" :disabled="props.controller.busy.value||!store.online||awaitingConfirmation" @click="props.controller.save()">重试保存正文</button><button :disabled="props.controller.busy.value||!store.online" @click="props.controller.refresh()">载入最新信息</button><button v-if="props.controller.lastAccepted.value" @click="emit('read',props.controller.lastAccepted.value)">接着读已加入的章节</button><button v-if="!historical&&!props.controller.preview.value&&!props.controller.active.value&&value.acceptedPrefix<value.requestedChapters" :disabled="props.controller.busy.value||!store.online||awaitingConfirmation" @click="rewriteOpen=!rewriteOpen"><RotateCcw :size="16"/>{{props.controller.rewriteIntent.value?'确认同一次重写请求':'重写未保存的章节'}}</button><button v-if="props.controller.preview.value" @click="props.controller.selectVersion(props.controller.state.value!.candidateVersion)">返回当前候选</button></div>
  <AcceptedBasisPanel v-if="value.acceptedEventBasis" :basis="value.acceptedEventBasis"/><p v-if="value.acceptedBasisUnavailable" class="generation-hints" role="status">续写依据暂时无法核对，正文仍保留。</p>
  <details class="writing-history" @toggle="($event.target as HTMLDetailsElement).open&&props.controller.loadVersions()"><summary>候选版本</summary><select v-if="props.controller.versions.value.length" v-model.number="versionChoice" aria-label="选择候选版本" @change="props.controller.selectVersion(versionChoice)"><option v-for="version in props.controller.versions.value" :key="version.candidateVersion" :value="version.candidateVersion">候选 {{version.candidateVersion}}</option></select></details><button @click="copy(value.taskId)">复制诊断 ID</button><small v-if="value.fee">{{value.fee.amount===null||value.fee.certainty!=='known'?(historical?'历史费用未记录':'费用暂未确认'):`费用 ${value.fee.amount} ${value.fee.currency||''}`}}</small>
  <form v-if="rewriteOpen&&!historical" class="generation-rewrite" @submit.prevent="rewrite"><label>这次希望怎样改写？<textarea v-model="wish" maxlength="2000" required rows="2"></textarea></label><button class="primary" :disabled="props.controller.busy.value||!store.online||awaitingConfirmation||!wish.trim()">确认新的写作请求</button><button type="button" @click="rewriteOpen=false">保留原候选</button></form><p v-if="props.controller.error.value||localError" class="error" role="alert">{{props.controller.error.value||localError}}</p><small v-if="props.controller.conflict.value" class="muted">正文已保留。请载入最新信息，再选择要保存的连续章节。</small><small v-if="!historical&&value.providerState==='unknown'" class="muted">本次调用与费用未确认，恢复不会自动再写一次。</small>
</section></template>
